CREATE TABLE IF NOT EXISTS oauth_tokens(connection_id TEXT NOT NULL PRIMARY KEY REFERENCES connections(id) ON DELETE CASCADE, org_id TEXT NOT NULL REFERENCES organizations(id), access_ciphertext TEXT NOT NULL CHECK(length(access_ciphertext) BETWEEN 1 AND 8192), access_nonce TEXT NOT NULL CHECK(length(access_nonce) BETWEEN 1 AND 128), access_wrapped_dek TEXT NOT NULL CHECK(length(access_wrapped_dek) BETWEEN 1 AND 2048), refresh_ciphertext TEXT CHECK(refresh_ciphertext IS NULL OR length(refresh_ciphertext) BETWEEN 1 AND 8192), refresh_nonce TEXT CHECK(refresh_nonce IS NULL OR length(refresh_nonce) BETWEEN 1 AND 128), refresh_wrapped_dek TEXT CHECK(refresh_wrapped_dek IS NULL OR length(refresh_wrapped_dek) BETWEEN 1 AND 2048), key_version INTEGER NOT NULL CHECK(key_version >= 1), algorithm TEXT NOT NULL CHECK(algorithm IN ('AES-GCM-256')), generation INTEGER NOT NULL CHECK(generation >= 1), scope TEXT NOT NULL DEFAULT '', expires_at_ms INTEGER, status TEXT NOT NULL CHECK(status IN ('healthy','failed','revoked')), consecutive_failures INTEGER NOT NULL DEFAULT 0 CHECK(consecutive_failures >= 0), last_failure_code TEXT, last_success_at TEXT, checked_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS oauth_tokens_org ON oauth_tokens(org_id);
